read_input <- function(x) {
  if (dir.exists(x)) {
    if (dir.exists(file.path(x, "filtered_feature_bc_matrix"))) {
      counts <- Read10X(data.dir = file.path(x, "filtered_feature_bc_matrix"))
    } else {
      counts <- Read10X(data.dir = x)
    }
  } else if (grepl("\\.(h5|hdf5)$", x, ignore.case = TRUE)) {
    counts <- Read10X_h5(x)
  } else if (grepl("\\.rds$", x, ignore.case = TRUE)) {
    obj <- readRDS(x)
    if (inherits(obj, "Seurat")) return(obj)
    counts <- obj
  } else if (grepl("\\.csv(\\.gz)?$", x, ignore.case = TRUE)) {
    counts <- read.csv(x, row.names = 1, check.names = FALSE)
    counts <- as.matrix(counts)
  } else if (grepl("\\.(tsv|txt)(\\.gz)?$", x, ignore.case = TRUE)) {
    counts <- read.delim(x, row.names = 1, check.names = FALSE)
    counts <- as.matrix(counts)
  } else {
    stop(paste("Unsupported input:", x))
  }

  if (is.list(counts)) {
    if ("Gene Expression" %in% names(counts)) {
      counts <- counts[["Gene Expression"]]
    } else {
      counts <- counts[[1]]
    }
  }

  counts
}

