read_counts <- function(path) {
  if (is.na(path) || !nzchar(path)) {
    stop("Please provide a raw count input path as the first command-line argument.")
  }
  if (dir.exists(path)) {
    files <- list.files(path, full.names = TRUE)
    if (any(grepl("\\.h5$", files, ignore.case = TRUE)) || any(grepl("\\.h5ad$", files, ignore.case = TRUE))) {
      h5file <- files[grepl("\\.h5$", files, ignore.case = TRUE)][1]
      if (is.na(h5file)) stop("No supported H5 file found in directory.")
      ext <- tolower(tools::file_ext(h5file))
      if (ext == "h5") {
        counts <- Read10X_h5(h5file)
      } else {
        stop("H5AD input is not directly supported in this script. Convert to 10X H5 or Matrix Market format.")
      }
    } else if (any(grepl("matrix\\.mtx(\\.gz)?$", files, ignore.case = TRUE))) {
      counts <- Read10X(data.dir = path)
    } else {
      stop("Directory input must contain 10X-formatted matrix files or a 10X H5 file.")
    }
  } else if (file.exists(path)) {
    ext <- tolower(tools::file_ext(path))
    if (ext %in% c("h5")) {
      counts <- Read10X_h5(path)
    } else if (ext %in% c("rds")) {
      counts <- readRDS(path)
    } else if (ext %in% c("mtx", "gz", "csv", "tsv", "txt")) {
      if (grepl("\\.csv$", path, ignore.case = TRUE)) {
        counts <- as.matrix(read.csv(path, row.names = 1, check.names = FALSE))
      } else if (grepl("\\.tsv$|\\.txt$|\\.gz$", path, ignore.case = TRUE)) {
        counts <- as.matrix(read.delim(path, row.names = 1, check.names = FALSE))
      } else if (grepl("\\.mtx$", path, ignore.case = TRUE) || grepl("\\.mtx\\.gz$", path, ignore.case = TRUE)) {
        stop("For Matrix Market input, provide a directory containing matrix.mtx, barcodes.tsv, and features.tsv.")
      } else {
        stop("Unsupported file type.")
      }
    } else {
      stop("Unsupported input format.")
    }
  } else {
    stop("Input path does not exist.")
  }
  counts
}

